   [33]={next_id=34, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="深海对这个人的相貌并不陌生——在黎苏根，她亲眼看过这个人在自己面前变成了一只怪物。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [34]={next_id=35, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这应当也是一个克隆体。", msg_color="", msg_size=0, talker="深海", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [35]={next_id=36, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="除了存在一些年龄上的差别之外，这张脸与丽娜几乎一模一样，深海心中意识到了什么。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [36]={next_id=37, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="提取克隆体的基因细胞进行培育，使其逆向生长，然后再将它移植到本体，从而替换已经衰老的身体组织……", msg_color="", msg_size=0, talker="深海", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [37]={next_id=38, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="对于未知的好奇令她克服了恐惧，深海靠近玻璃罐，凑上去仔细观察。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="泡在培养液中的“人”仿佛发现了她，缓缓睁开浮肿的眼睛，朝着她发出痛苦的嘶吼，神色好像有些哀伤。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="厚厚的有机玻璃隔绝了所有的声音，深海望着那副狰狞的模样，下意识后退了一步，发现自己似乎踩到了什么东西。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [40]={next_id=41, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="深海", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [41]={next_id=42, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是个笔记本，它的主人名为丽娜·德尔波。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [42]={next_id=43, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="第一阶段试验完成，077的身体素质远比想象中更好，或许真的可以凭借她开发出我所需要的神经病毒。\n玛尔斯曾经说我会后悔，到今天好像都成真了，只是我也没有办法，当时的情况下，我没有第二个选择。\n不，我并非背叛者，我只想保护她，保护我的孩子。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 873.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [43]={next_id=44, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="紧接着是密密麻麻的试验数据，深海快速将这些信息过了一遍，吃惊地发现都是些人体试验的对比数据，甚至还被记录者贴心地写上了年龄和试验时间。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [44]={next_id=45, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="深海压下心中的不适感，跳过这部分内容，继续往后翻，查看那些关键性的东西。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [45]={next_id=46, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="分别在克隆体、人类、还有机械身上进行了测试，主要还是人类，综合效果都不错。\n077没有发现我在她身上执行的试验，反倒是维里塔似乎注意到了什么，我必须再小心一点。\n她最近好像有些其他打算，我得抓紧时间。\n找个机会去一次黎苏根吧，克里安卡……我愿意用这个被她认可的名字来称呼她。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 873.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [46]={next_id=47, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="对方的字迹明显乱了起来，纸上还有几个洞，好像是某些腐蚀性的溶液造成的。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [47]={next_id=48, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="维里塔？", msg_color="", msg_size=0, talker="深海", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [48]={next_id=49, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这个名字同样在史书中臭名昭著。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [49]={next_id=50, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的全名是维里塔·坎贝尔，普瑞斯毁灭时，她正奉因斐诺大帝的命令出使尤赞坦。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [50]={next_id=51, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="随着普瑞斯那场史无前例的锚点降临，她自动继承了坎贝尔公爵的名号，随后成功游说了尤赞坦当局，在尤赞坦掀起了一场声势浩大的动乱。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [51]={next_id=52, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这场争斗长达六年，最终以伊南姆为首的几个家族胜出，这几个家族瓜分了尤赞坦的政权，随后处死维里塔，结束了争斗。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [52]={next_id=53, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当时她的尸体明明已经被公之于众了……难道说……", msg_color="", msg_size=0, talker="深海", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [53]={next_id=54, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="深海抬起头，看向泡在培养液中的那个已然面目全非的克隆体——她正贴在玻璃壁上，死死看着这个方向。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [54]={next_id=55, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她深吸一口气，急匆匆又把笔记翻了几页。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [55]={next_id=56, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……克里安卡那孩子还是太固执了，我不得不把她骗了回来。\n我的计划未必能成功，我不敢保证自己一定能阻止维里塔。\n她还是像以前那样谨慎，即使是我都没办法接近她。\n如果不能做到，那我的努力就全都白费了，但我还是想要试试。\n毕竟这是她的心愿。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 873.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [56]={next_id=57, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="假如有人看到了这个笔记，就说明我没能回来。\n不论你是谁，如果一切已经结束的话，就请你打开那个培养舱吧。\n里面的营养液可以隔绝维里塔对她神经芯片的定位，同时保障她的身体机能。\n培养舱的密码是[玩家名字]，她心中唯一的惦念，我不希望我的女儿在沉睡中度过漫长的时间。\n我想要让我最伟大和了不起的作品行走在未来的大地上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 873.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [57]={next_id=58, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="再往后还有两行字，力道之大几乎要将纸张戳破了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [58]={next_id=59, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="克里安卡，了不起的奇迹。\n绝不能让她为了维里塔的野心所牺牲。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 873.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
