   [62]={next_id=63, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她是维里塔·坎贝尔，因斐诺最后一位坎贝尔公爵。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [63]={next_id=64, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在普瑞斯毁灭后，她说服了后来掌权的伊南姆家族，成功逃脱了制裁，并要求伊南姆秘密协助她在这片黄沙中建造了这间罪恶的实验室。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [64]={next_id=65, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="经过这些年的调查，我发现她想要再现普瑞斯的灾难……虽然她并不将那认为是灾难。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [65]={next_id=66, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="维瑟内特认真看向你，告知你自己发现的信息。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [66]={next_id=67, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她认为自己全然洞悉并了解因斐诺的研究，能够在这个时代恢复那个王国，并避开那个厄运。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="厄运？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [68]={next_id=69, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当代泰诺星的研究普遍认为，因斐诺这个名字代表着罪恶和不幸。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [69]={next_id=70, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="罪恶自然不必多说，至于不幸，一个发展已然登峰造极的国度在灾难的开端以猝不及防的势头被毁灭，从而早早地离开了牌桌。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [70]={next_id=71, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="嗯，维里塔是这么认为的。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [71]={next_id=72, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的声调中隐隐带着几分哀伤。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [72]={next_id=73, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="维里塔相信，当初的因斐诺人早就达到了“进化”的标准，只是因为不幸才被修格尔选中。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [73]={next_id=74, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以她这么多年以来，一直在这片地下王国里模拟当时的普瑞斯城市。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [74]={next_id=75, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="模拟普瑞斯……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [75]={next_id=76, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你不禁看向周围漆黑的石壁和上面雕镂的种种怪异花纹，回想起来黎苏根地下那片遗迹。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
