   [78]={next_id=79, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你的眉头轻轻跳了下。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [79]={next_id=80, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我拿到的某些研究笔记里写道，高阶文明的社会形态就是网状，这个研究成果继承自因斐诺。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [80]={next_id=81, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="维瑟内特半蹲下，拿手指在地面上为你画了简单的示意图。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [81]={next_id=82, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="以一位王作为中心，向周围辐射和扩散，就这样不断地向外扩充和衔接。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_503.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
