   [177]={next_id=178, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="尽管眼前之人正在努力模仿着克里安卡，但你仍旧看一眼就可以确认，不远处这个人没有那些充沛的情感，即使容貌一致，也掩盖不了她只是一团生物材料和机械聚合体这一本质。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_406.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [178]={next_id=179, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="克隆体从异变体群中穿了过来，安静地站在离你很近的地方，你与她对上视线，感到了一阵反胃。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_406.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
